#!/usr/bin/env bash
# KOKPIT_UI_V2 — Nakit&Tahsilat boşluğu doldur (müşteri vade dağılımı) + kırılım kartları scroll (tüm satırlar).
set -e
cd /opt/krb-assessment
KOKF=shells/kokpit.html
[ -f "$KOKF" ] || { echo "HATA: kokpit.html yok"; exit 1; }
cp "$KOKF" "$KOKF.bak.$(date +%s)"
printf '%s' '' | base64 -d > "$KOKF"
echo "kokpit.html satır: $(wc -l < "$KOKF")"
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
docker exec krb-assessment sh -c "grep -c 'rows-scroll\|Müşteri tahsilat vade dağılımı' /app/shells/kokpit.html" || true
echo "== DONE =="
